TOKENS='\n  :root{\n    --bg:#ffffff; --surface:#f8fafc; --surface-2:#f1f5f9; --border:#e2e8f0;\n    --border-strong:#cbd5e1; --text:#0f172a; --text-muted:#475569; --text-dim:#64748b;\n    --accent:#2563eb; --accent-soft:#eff6ff; --accent-border:#bfdbfe;\n    --ok:#15803d; --ok-soft:#f0fdf4; --warn:#b45309; --warn-soft:#fffbeb;\n    --radius:8px; --radius-sm:5px;\n    --s1:4px; --s2:8px; --s3:12px; --s4:16px; --s5:24px; --s6:32px;\n    --mono:ui-monospace,SFMono-Regular,Menlo,Consolas,"Liberation Mono",monospace;\n    --sans:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;\n  }\n  [data-theme="dark"]{\n    --bg:#0b1120; --surface:#0f172a; --surface-2:#1e293b; --border:#1e293b;\n    --border-strong:#334155; --text:#e2e8f0; --text-muted:#94a3b8; --text-dim:#64748b;\n    --accent:#60a5fa; --accent-soft:#172554; --accent-border:#1e40af;\n    --ok:#86efac; --ok-soft:#052e16; --warn:#fcd34d; --warn-soft:#2a1f05;\n  }\n'
BASE='\n  *{box-sizing:border-box;}\n  body{margin:0; padding:var(--s5); background:var(--bg); color:var(--text);\n       font-family:var(--sans); font-size:14px; line-height:1.5;}\n  .wrap{max-width:980px; margin:0 auto;}\n\n  /* ---- page chrome (mockup only, not part of the proposal) ---- */\n  .mockbar{display:flex; align-items:center; gap:var(--s3); flex-wrap:wrap;\n    margin-bottom:var(--s4); padding-bottom:var(--s3);\n    border-bottom:1px solid var(--border);}\n  .mockbar h1{font-size:15px; margin:0; font-weight:650;}\n  .mockbar .tag{font-family:var(--mono); font-size:10.5px; color:var(--text-dim);\n    border:1px solid var(--border); border-radius:var(--radius-sm); padding:1px 6px;}\n  .mockbar button{margin-left:auto; font:inherit; font-size:11.5px; cursor:pointer;\n    background:var(--surface); color:var(--text-muted);\n    border:1px solid var(--border-strong); border-radius:var(--radius-sm);\n    padding:3px 10px;}\n  .mockbar button:hover{color:var(--text); border-color:var(--accent);}\n\n  h2.sec{font-size:12px; text-transform:uppercase; letter-spacing:.05em;\n    color:var(--text-dim); font-weight:650; margin:var(--s5) 0 var(--s2);}\n\n  /* ---- I/O summary: density reference, copied verbatim from Layout2 ---- */\n  .io-summary{display:grid; grid-template-columns:repeat(auto-fit, minmax(200px, 1fr));\n    gap:var(--s2); margin-bottom:var(--s3); padding:var(--s3);\n    background:var(--surface); border:1px solid var(--border); border-radius:var(--radius);}\n  .io-summary h3{font-size:11px; text-transform:uppercase; letter-spacing:.05em;\n    color:var(--accent); margin:0 0 var(--s1); font-weight:650; grid-column:1/-1;}\n  .io-item{font-size:11.5px; line-height:1.4;}\n  .io-item b{color:var(--text); font-weight:600; display:block; margin-bottom:2px;}\n  .io-item code{font-family:var(--mono); font-size:10.5px;\n    background:var(--surface-2); padding:1px 3px; border-radius:2px;}\n  .io-item .type{color:var(--text-dim);}\n\n  /* ---- shared grounding typography (all 3 options share this) ---- */\n  .g-body{font-size:11.5px; line-height:1.45; color:var(--text-muted);}\n  .g-body p{margin:0 0 var(--s1);}\n  .g-body p:last-child{margin-bottom:0;}\n  .g-body ul{margin:0; padding:0; list-style:none;}\n  .g-body li{position:relative; padding-left:var(--s3); margin-bottom:2px;}\n  .g-body li:last-child{margin-bottom:0;}\n  .g-body li::before{content:""; position:absolute; left:3px; top:.55em;\n    width:3px; height:3px; border-radius:50%; background:var(--border-strong);}\n  .g-body b{color:var(--text); font-weight:600;}\n  .g-body code{font-family:var(--mono); font-size:10.5px;\n    background:var(--surface-2); padding:1px 3px; border-radius:2px;}\n\n  /* visible focus everywhere (a11y requirement) */\n  :focus-visible{outline:2px solid var(--accent); outline-offset:2px; border-radius:3px;}\n\n  .sr-only{position:absolute; width:1px; height:1px; padding:0; margin:-1px;\n    overflow:hidden; clip:rect(0 0 0 0); white-space:nowrap; border:0;}\n\n  /* ---- continuing page content, proves "in context" ---- */\n  .after{margin-top:var(--s4); border:1px solid var(--border);\n    border-radius:var(--radius); overflow:hidden;}\n  .after .bar{background:var(--surface-2); padding:var(--s1) var(--s3);\n    font-family:var(--mono); font-size:10.5px; color:var(--text-dim);\n    border-bottom:1px solid var(--border);}\n  .after pre{margin:0; padding:var(--s3); font-family:var(--mono); font-size:11.5px;\n    color:var(--text-muted); overflow-x:auto;}\n\n  .note{margin-top:var(--s5); padding-top:var(--s3); border-top:1px solid var(--border);\n    font-size:11px; color:var(--text-dim);}\n  .note b{color:var(--text-muted);}\n'
THEME_JS="\n  (function(){\n    var b=document.getElementById('themeBtn');\n    if(!b) return;\n    b.addEventListener('click',function(){\n      var r=document.documentElement;\n      var dark=r.getAttribute('data-theme')==='dark';\n      r.setAttribute('data-theme', dark?'light':'dark');\n      b.setAttribute('aria-pressed', String(!dark));\n      b.textContent = dark ? 'Dark theme' : 'Light theme';\n    });\n  })();\n"
IO='\n    <div class="io-summary">\n      <h3>I/O Summary</h3>\n      <div class="io-item">\n        <b>discordance</b>\n        <span class="type">Input:</span> <code>diff: ndarray(B1,B2,C)</code>, <code>p: ndarray(C)</code>, <code>v: ndarray(C)</code><br>\n        <span class="type">Output:</span> <code>ndarray(B1,B2,C)</code> in [0,1]<br>\n        <span class="type">Constraint:</span> <code>p &le; v</code> (validated upstream)\n      </div>\n      <div class="io-item">\n        <b>Formula</b>\n        <span class="type">d_j:</span> piecewise linear in [-v, -p] range<br>\n        <span class="type">Veto:</span> <code>d_j = 1</code> when diff &le; -v<br>\n        <span class="type">None:</span> <code>d_j = 0</code> when diff &ge; -p\n      </div>\n      <div class="io-item">\n        <b>Role in Pipeline</b>\n        <span class="type">Used by:</span> credibility module<br>\n        <span class="type">Effect:</span> May reduce credibility via veto\n      </div>\n    </div>\n'
AFTER='\n    <h2 class="sec">Step 1 &middot; Compute per-criterion discordance</h2>\n    <div class="after">\n      <div class="bar">electre3/discordance.py</div>\n<pre>d = discordance(diff, p=p, v=v)\nassert d.min() &gt;= 0.0 and d.max() &lt;= 1.0</pre>\n    </div>\n'
